def minMirrorPairDistance(nums):
    # A mirror pair (i, j), i < j, needs reverse(nums[i]) == nums[j].
    # Scan left to right; for each j, the closest earlier i is where reverse(nums[i])
    # equals nums[j]. Keep the most recent index for each reverse-value.
    def rev(x):
        return int(str(x)[::-1])

    last_rev = {}  # reverse(nums[i]) -> most recent index i
    best = -1
    for j, v in enumerate(nums):
        if v in last_rev:
            d = j - last_rev[v]
            if best == -1 or d < best:
                best = d
        last_rev[rev(v)] = j
    return best
